type ReviewEvidence struct {
	Complete    bool
	Pass        bool
	Carry       bool
	Disposition bool
}

type ReviewCapUsage struct {
	ReviewRounds int
	RepairRounds int
}

func (usage ReviewCapUsage) Total() int { return usage.ReviewRounds + usage.RepairRounds }

// QueueValidationFixResult describes whether an automatic instruction was added.
type QueueValidationFixResult struct {
	MessageID       int64
	Seq             int
	RoundsUsed      int
	Queued          bool
	Coalesced       bool
	Exhausted       bool
	SharedExhausted bool
}

// ValidationContinuitySnapshot binds a done Signal to the current fix rounds.
type ValidationContinuitySnapshot struct {
	Heads         []string
	LatestRoundID int64
}

// ErrValidationHeadsChanged means a new fix instruction arrived after continuity was checked.
var ErrValidationHeadsChanged = errors.New("validation fix instructions changed while recording done")

// QueueValidationFixInstruction records a fix round and queues or extends the
// unsent validation message for the same head in one transaction.
func (db *DB) QueueValidationFixInstruction(ctx context.Context, taskID int64, kind, expectedBaseHead, dedupeKey, body string) (QueueValidationFixResult, error) {
	return db.queueValidationFixInstruction(ctx, taskID, kind, expectedBaseHead, nil, dedupeKey, body, nil, nil, nil)
}

// QueueValidationFixInstructionWithinBudget records a fix round only while its
// per-kind budget remains. The budget check and insertion share one transaction.
func (db *DB) QueueValidationFixInstructionWithinBudget(ctx context.Context, taskID int64, kind, expectedBaseHead, dedupeKey, body string, maxRounds int) (QueueValidationFixResult, error) {
	if maxRounds < 0 {
		return QueueValidationFixResult{}, fmt.Errorf("validation fix round budget cannot be negative")
	}
	return db.queueValidationFixInstruction(ctx, taskID, kind, expectedBaseHead, nil, dedupeKey, body, &maxRounds, nil, nil)
}

// QueueValidationFixInstructionWithSharedBudget enforces the frozen per-kind
// limit and shared Review/CI cap in the same admission transaction.
func (db *DB) QueueValidationFixInstructionWithSharedBudget(ctx context.Context, taskID int64, kind, expectedBaseHead, dedupeKey, body string, maxRounds, sharedMax int) (QueueValidationFixResult, error) {
	if maxRounds < 0 || sharedMax < 1 {
		return QueueValidationFixResult{}, fmt.Errorf("invalid validation fix budget")
	}
	return db.queueValidationFixInstruction(ctx, taskID, kind, expectedBaseHead, nil, dedupeKey, body, &maxRounds, &sharedMax, nil)
}

// QueueReviewFixInstruction records one whole-pattern Review fix round. A
// workspace instruction names every changed Member head, and expectedBaseHead
// must be their digest. A nil budget is not enforced.
func (db *DB) QueueReviewFixInstruction(ctx context.Context, taskID int64, expectedBaseHead string, members []ValidationFixMemberHead, dedupeKey, body string, maxRounds, sharedMax *int) (QueueValidationFixResult, error) {
	if (maxRounds != nil && *maxRounds < 0) || (sharedMax != nil && *sharedMax < 1) {
		return QueueValidationFixResult{}, fmt.Errorf("invalid validation fix budget")
	}
	if len(members) > 0 {
		seen := map[string]bool{}
		for _, member := range members {
			if member.Repository == "" || seen[member.Repository] || !validValidationSHA(member.ExpectedBaseHead) || member.CandidateID < 0 {
				return QueueValidationFixResult{}, fmt.Errorf("invalid workspace Member head for a Review fix")
			}
			seen[member.Repository] = true
		}
		if expectedBaseHead != ValidationMemberHeadsDigest(members) {
			return QueueValidationFixResult{}, fmt.Errorf("workspace Review fix head must be the digest of its Member heads")
		}
	}
	return db.queueValidationFixInstruction(ctx, taskID, "review", expectedBaseHead, members, dedupeKey, body, maxRounds, sharedMax, nil)
}

func (db *DB) QueueProviderReviewFixInstruction(ctx context.Context, taskID int64, expectedBaseHead string, members []ValidationFixMemberHead, dedupeKey, body string, patterns []int, maxRounds, sharedMax *int) (QueueValidationFixResult, error) {
	if len(patterns) == 0 {
		return QueueValidationFixResult{}, fmt.Errorf("provider Review fixes require selected findings")
